function readCampusBiteStorage(key, fallback) {
  try {
    const value = JSON.parse(localStorage.getItem(key));
    return value == null ? fallback : value;
  } catch (error) {
    console.warn('Ignoring invalid saved data for ' + key, error);
    return fallback;
  }
}
function saveCart() {
  try {
    localStorage.setItem('campusbite_cart', JSON.stringify(cart));
    if (cart.length && activeOutlet) localStorage.setItem('campusbite_cart_outlet', activeOutlet);
    else if (!cart.length) localStorage.removeItem('campusbite_cart_outlet');
  } catch (error) {
    console.error('Could not save cart:', error);
  }
}
