function normalizeRole(role) {
  return String(role || 'CUSTOMER').replace(/^ROLE_/i, '').toLowerCase();
}

const API_BASE = 'http://localhost:8080';

function showUserDashboard() {
  $('authOpen').classList.add('hidden');
  $('userGreeting').textContent = user?.name ? `Hi, ${user.name}` : '';
  $('userGreeting').classList.toggle('hidden', !user?.name);
  $('logoutBtn').classList.remove('hidden');
  $('queueNav').classList.remove('hidden');
  $('roleBanner').classList.remove('hidden');

  $('roleLabel').textContent = ({
    customer: '🎓 Customer / Student',
    staff: '👩‍🍳 Canteen Staff',
    admin: '📋 Admin',
    owner: '👑 Owner'
  })[user.role];

  $('ordersNav').classList.toggle('hidden', user.role !== 'customer');
  $('orders').classList.toggle('hidden', user.role !== 'customer');
  $('sunflowerNav').classList.toggle('hidden', user.role !== 'customer');

  ['staffPanel', 'adminPanel', 'ownerPanel'].forEach(x =>
    $(x).classList.add('hidden')
  );

  if (user.role === 'staff') $('staffPanel').classList.remove('hidden');

  if (user.role === 'admin') $('adminPanel').classList.remove('hidden');

  if (user.role === 'owner') {
    $('ownerPanel').classList.remove('hidden');
    $('adminPanel').classList.remove('hidden');
  }

  if (user.role !== 'customer') {
    $('menu').classList.add('hidden');
  } else if (activeOutlet) {
    $('menu').classList.remove('hidden');
  }

  refreshAll();

  if (user.role === 'customer') {
    renderOrders();
  }
}

$('authForm').onsubmit = async e => {
  e.preventDefault();

  const d = Object.fromEntries(new FormData(e.target));

  const endpoint = authMode === 'register'
    ? '/api/auth/register'
    : '/api/auth/login';

  const requestBody = authMode === 'register'
    ? {
      name: d.name,
      email: d.email,
      password: d.password,
      role: d.role || 'CUSTOMER',
      assignedOutlet: d.role === 'STAFF' ? d.assignedOutlet : null,
      accessCode: d.role && d.role !== 'CUSTOMER' ? (d.accessCode || '') : null
    }
    : {
      email: d.email,
      password: d.password
    };

  try {
    $('authSubmit').disabled = true;
    $('authSubmit').textContent = 'Please wait...';

    const response = await fetch(API_BASE + endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(requestBody)
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.message || data.detail || 'Authentication failed');
    }

    const authenticatedRole = normalizeRole(data.role);
    if (authMode === 'login' && authenticatedRole !== normalizeRole(d.loginRole)) {
      const roleName = authenticatedRole.charAt(0).toUpperCase() + authenticatedRole.slice(1);
      throw new Error(`This account is registered as ${roleName}. Choose that role and try again.`);
    }

    localStorage.setItem('campusbite_token', data.token);

    user = {
      name: data.name,
      email: data.email,
      role: authenticatedRole,
      assignedOutlet: data.assignedOutlet || ''
    };
    localStorage.setItem('campusbite_user', JSON.stringify(user));

    modal('authModal', false);
    e.target.reset();

    showUserDashboard();

    toast(
      authMode === 'register'
        ? 'Account created successfully! 💗'
        : 'Welcome back, ' + user.name + '! 💗'
    );

  } catch (error) {
    console.error('Authentication error:', error);
    toast(error.message || 'Could not connect to the backend');
  } finally {
    $('authSubmit').disabled = false;
    $('authSubmit').textContent =
      authMode === 'login' ? 'Login →' : 'Create account →';
  }
};

