function orderRows() {
  let visible = orders.filter(o => o.status !== 'Cancelled' && (user?.role === 'owner' || user?.role === 'admin' || !activeOutlet || o.outlet === activeOutlet));
  const isActive = o => !['Delivered', 'Cancelled'].includes(o.status);
  // live position = place among the ACTIVE orders of the same outlet (re-numbers itself whenever an order is delivered or cancelled)
  const pos = o => isActive(o) ? 1 + visible.filter(x => isActive(x) && x.outlet === o.outlet && x.num < o.num).length : 0;
  visible = visible.slice().sort((a, b) => (isActive(b) - isActive(a)) || String(a.outlet).localeCompare(String(b.outlet)) || (isActive(a) ? a.num - b.num : b.num - a.num));
  const next = { Placed: ['Accepted', 'Accept ✅'], Accepted: ['Preparing', 'Start preparing 👩‍🍳'], Preparing: ['Ready', 'Mark READY 🔔 notify customer'], Ready: ['Delivered', 'Mark delivered ✔'] };
  const actions = o => (o.status === 'Ready' ? '<small>Awaiting customer collection</small>' : next[o.status] ? `<button class="small-btn" data-next="${o.id}">${next[o.status][1]}</button>` : '<small>Done</small>')
    + (['Placed', 'Accepted'].includes(o.status) ? ` <button class="small-btn danger-btn" data-cancelorder="${o.id}">Cancel ✖</button>` : '');
  const paymentCell = o => String(o.paymentStatus || '').toUpperCase() === 'PAID'
    ? '<span class="good">Paid ✅</span>'
    : ['Delivered', 'Cancelled'].includes(o.status) ? '<small>—</small>' : `<button class="small-btn" data-mark-paid="${o.id}">Mark paid</button>`;
  return visible.length ? table('<tr><th>Queue</th><th>Customer</th><th>Outlet</th><th>Items / cooking request</th><th>Total</th><th>Payment</th><th>Status</th><th>Actions</th></tr>' + visible.map(o => `<tr><td>${isActive(o) ? '<b>#' + pos(o) + '</b><br><small>token ' + o.num + '</small>' : '—'}</td><td>${safe(o.customer)}</td><td>${safe(o.outlet || '')}</td><td>${o.items.map(x => x.name + ' ×' + x.qty).join(', ')}${o.cookingRequest ? `<br><strong class="queue-cooking-request">👩‍🍳 Request: ${safe(o.cookingRequest)}</strong>` : ''}</td><td>${money(o.total)}</td><td>${paymentCell(o)}</td><td>${o.status}</td><td>${actions(o)}</td></tr>`).join('')) : '<p class="dash-note">No orders in the queue yet.</p>'
}
function refreshAll() { if (user?.role === 'customer') renderOrders(); let sales = orders.filter(o => o.status !== 'Cancelled').reduce((s, o) => s + o.total, 0), low = foods.filter(f => f.stock <= f.lowStockAt).length, active = orders.filter(o => !['Delivered', 'Cancelled'].includes(o.status)).length; $('staffStats').innerHTML = stat('Active orders', active) + stat('Low-stock items', low) + stat('Orders today', orders.length); $('staffQueue').innerHTML = orderRows(); $('staffInventory').innerHTML = stockRows(); $('adminStats').innerHTML = stat('Total sales', money(sales)) + stat('Orders received', orders.length) + stat('Low-stock alerts', low); $('inventoryList').innerHTML = stockRows(); renderAdminOutletBar(); $('adminMenu').innerHTML = (isTeamLead() && !adminOutlet ? pickCanteenNote : '') + foods.filter(inScope).map(f => `<div class="manage-row"><span>${f.emoji} ${safe(f.name)} · ${money(f.price)}</span><span>${f.available ? 'Available' : 'Disabled'}</span><button data-toggle="${f._id}">${f.available ? 'Disable' : 'Enable'}</button><button data-edit="${f._id}">Edit price</button><button data-delete="${f._id}" class="danger-btn">Delete</button></div>`).join(''); $('allOrders').innerHTML = orderRows(); $('salesSummary').innerHTML = `<p>Total revenue: <b>${money(sales)}</b></p><p>Completed orders: <b>${orders.filter(o => o.status === 'Delivered').length}</b></p>`; $('ownerStats').innerHTML = stat('Revenue', money(sales)) + stat('Menu items', foods.length) + stat('Low-stock alerts', low) + stat('Team members', team.length); $('teamList').innerHTML = team.map(t => `<div class="inventory-row">${safe(t.name)} · ${t.role}</div>`).join(''); $('supplierList').innerHTML = suppliers.map(s => `<div class="inventory-row">🚚 ${safe(s.name)} · ${safe(s.phone || 'No contact')}</div>`).join(''); $('purchaseFood').innerHTML = foods.filter(f => !isTeamLead() || !adminOutlet || f.outlet === adminOutlet).map(f => `<option value="${f._id}">${f.name}</option>`).join(''); $('ownerLogs').innerHTML = logs.slice(-8).reverse().map(l => `<div class="inventory-row">${l}</div>`).join('') || '<p class="dash-note">No purchase or stock adjustments recorded.</p>'; $('ownerPerformance').innerHTML = [...foods].sort((a, b) => b.sold - a.sold).slice(0, 5).map(f => `<div class="inventory-row">${f.emoji} ${f.name}<b>${f.sold} sold</b></div>`).join(''); }
