$('foodForm').onsubmit = e => { e.preventDefault(); let d = Object.fromEntries(new FormData(e.target)); foods.push({ _id: String(id++), name: d.name, outlet: d.outlet || activeOutlet || 'Nescafé', category: d.category, price: +d.price, stock: +d.stock, lowStockAt: +d.lowStockAt, emoji: d.emoji || '🍽️', description: d.description || 'Freshly prepared at CampusBite', available: true, sold: 0 }); e.target.reset(); refreshAll(); renderFilters(); renderFoods(); toast('New menu item added') }; $('teamForm').onsubmit = e => { e.preventDefault(); let d = Object.fromEntries(new FormData(e.target)); team.push(d); e.target.reset(); refreshAll(); toast('Team member added to demo list') }; $('supplierForm').onsubmit = e => { e.preventDefault(); let d = Object.fromEntries(new FormData(e.target)); suppliers.push(d); e.target.reset(); refreshAll(); toast('Supplier added') }; $('purchaseForm').onsubmit = e => { e.preventDefault(); let d = Object.fromEntries(new FormData(e.target)), f = foods.find(x => x._id === d.foodId); f.stock += Number(d.quantity); logs.push(`Purchase: ${f.name} +${d.quantity} units · Cost ${money(d.cost)}`); e.target.reset(); refreshAll(); renderFoods(); toast('Purchase recorded; stock increased') };['staffRefresh', 'adminRefresh', 'ownerRefresh', 'refreshOrders'].forEach(x => $(x).onclick = () => { refreshAll(); renderOrders(); toast('Dashboard refreshed') }); $('menu').classList.add('hidden'); renderFilters(); renderFoods(); renderCart(); refreshAll();
